"use strict";(self.webpackChunkmy_website=self.webpackChunkmy_website||[]).push([[1931],{81281:e=>{e.exports=JSON.parse('{"tag":{"label":"Data Management","permalink":"/labs/tags/data-management","allTagsPath":"/labs/tags","count":3,"items":[{"id":"image-search-bench","title":"Benchmarking AI-Powered Image Search at Scale","description":"As we develop AI-powered image search across Sage\u2019s nationwide cyberinfrastructure, one challenge quickly stood out:","permalink":"/labs/image-search-bench"},{"id":"image-search","title":"Sage Image Search","description":"In the age of AI-powered tools, searching through thousands of images shouldn\'t just be about basic metadata. What if you could search by meaning? That\u2019s exactly what this project aims to do: combine the best of semantic understanding and keyword precision into one powerful hybrid image search engine to help you find relevant image series for your project.","permalink":"/labs/image-search"},{"id":"sage-mcp","title":"Sage MCP: AI-Powered Edge Computing Interface","description":"In the rapidly evolving landscape of AI and edge computing, accessing complex cyberinfrastructure shouldn\'t require memorizing APIs or writing custom scripts. What if you could simply ask for what you need in plain English? That\'s the vision behind Sage MCP, a Model Context Protocol server that bridges the gap between Large Language Models and the Sage edge computing ecosystem, making advanced sensor networks accessible through natural conversation.","permalink":"/labs/sage-mcp"}],"unlisted":false}}')}}]);